    module: "14. Special Populations and Culturally Relevant Practice",
    topic: "Trauma-Informed Care (TIC)",
    difficulty: "Advanced",
    questionText: "Under SAMHSA Principle 5: 'Empowerment, Voice, and Choice,' what clinical strategy empowers consumer agency on an acute mental health ward?",
