    module: "14. Special Populations and Culturally Relevant Practice",
    topic: "Trauma-Informed Care (TIC)",
    difficulty: "Advanced",
    questionText: "Why are traditional coercive psychiatric practices—such as physical restraint holds, mechanical restraints, locked seclusion, and unexpected room searches—particularly catastrophic and retraumatizing for individuals with histories of childhood sexual or physical abuse?",
