    correctAnswer: "C",
    explanation: "Historical trauma (Brave Heart) refers to the cumulative emotional and psychological wounding across one's lifespan and across generations, resulting from cataclysmic collective trauma inflicted on a group. In Indigenous communities, the legacy of genocide, forced assimilation in residential schools, family separation, and outlawing of spiritual practices produces intergenerational distress, substance vulnerability, and unresolved grief.",
